-- AgencyOS hardening migration.
--
-- Data fixes (hand-written, not generated by Prisma):
--   1. Duplicate CampaignDestination rows (same campaign + same destination) are
--      removed, keeping the oldest, so the new unique indexes can be created.
--   2. Existing Telegram destinations were auto-"authorized" at creation without any
--      proof of admin consent. They are reset to PENDING_VERIFICATION (the column
--      default) and isAuthorized=false: nothing may post until an admin re-verifies.
--
-- Rollback: see rollback.sql in this directory (not run by Prisma).

DELETE FROM "CampaignDestination" a
USING "CampaignDestination" b
WHERE a."campaignId" = b."campaignId"
  AND (a."createdAt" > b."createdAt" OR (a."createdAt" = b."createdAt" AND a."id" > b."id"))
  AND (
    (a."telegramDestinationId" IS NOT NULL AND a."telegramDestinationId" = b."telegramDestinationId")
    OR (a."integrationId" IS NOT NULL AND a."integrationId" = b."integrationId")
  );

-- CreateEnum
CREATE TYPE "DestinationAuthStatus" AS ENUM ('PENDING_VERIFICATION', 'ACTIVE', 'SUSPENDED', 'REVOKED', 'EXPIRED', 'DISCONNECTED');

-- CreateEnum
CREATE TYPE "PostingJobStatus" AS ENUM ('PENDING', 'SENDING', 'SUCCEEDED', 'BLOCKED', 'DEAD', 'CANCELLED', 'UNCERTAIN');

-- CreateEnum
CREATE TYPE "AgencyRole" AS ENUM ('AGENCY_OWNER', 'AGENCY_ADMIN', 'SALES_MANAGER', 'SALES_EXECUTIVE', 'CAMPAIGN_MANAGER', 'CONTENT_EDITOR', 'ANALYST', 'CLIENT');

